import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice returns an invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2024-01-15');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 2);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice normalizes lowercase customer ID', () => {
  const r = createInvoice({
    customerId: 'c-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID with spaces', () => {
  const r = createInvoice({
    customerId: '  c-002  ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
});

test('createInvoice normalizes mixed-case customer ID with spaces', () => {
  const r = createInvoice({
    customerId: '  c-007 ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-007');
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
});

test('createInvoice reports unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice validates issueDate format', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '01/15/2024',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r1, { ok: false, error: 'DATE_INVALID' });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r2, { ok: false, error: 'DATE_INVALID' });

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r3, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects missing lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice validates quantity is a positive integer', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(r1, { ok: false, error: 'QTY_INVALID' });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: -1 }],
  });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r3, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice validates SKU exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  };
  const originalLines = JSON.stringify(input.lines);
  createInvoice(input);
  assert.equal(JSON.stringify(input.lines), originalLines);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 2, unitPrice: 8500 };
  assert.equal(lineTotal(line), 17000);
});

test('lineTotal returns integer cents', () => {
  const line = { qty: 1, unitPrice: 6000 };
  assert.equal(lineTotal(line), 6000);
  assert.equal(Number.isInteger(lineTotal(line)), true);
});

test('lineTotal handles single unit', () => {
  const line = { qty: 1, unitPrice: 120000 };
  assert.equal(lineTotal(line), 120000);
});

test('invoiceTotals sums line totals', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, vatRate: 0 },
      { qty: 5, unitPrice: 9500, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 64500, discount: 0, vat: 0, total: 64500 });
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 3, unitPrice: 6000, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 18000, discount: 0, vat: 0, total: 18000 });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 8500, vatRate: 0 },
      { qty: 2, unitPrice: 9500, vatRate: 0 },
      { qty: 3, unitPrice: 6000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 45500, discount: 0, vat: 0, total: 45500 });
});

test('invoiceTotals with an invoice from createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  // DES-HOUR: 17000 * 21% = 3570, DEV-HOUR: 9500 * 21% = 1995
  // total VAT = 5565
  assert.deepEqual(totals, { subtotal: 26500, discount: 0, vat: 5565, total: 32065 });
});

test('invoiceTotals returns a new object', () => {
  const invoice = { lines: [{ qty: 1, unitPrice: 100 }] };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('addLine adds a new line to an invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r2.value.lines[1].qty, 3);
  assert.equal(r2.value.lines[1].name, 'Development (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
