    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 50, vatRate: 21 },
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: subtotal=10000, discount=5000, after=5000, vat=1050
  // Line 2: subtotal=10000, discount=0, after=10000, vat=2100
  // total subtotal = 20000, total discount = 5000, total vat = 3150
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 5000);
  assert.equal(totals.vat, 3150);
  assert.equal(totals.total, 18150);
});

test('invoiceTotals with tier discount and VAT', () => {
