  assert.equal(JSON.stringify(input), original);
});

test('invoiceTotals includes voucher field', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals subtracts voucher from total', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 1000 },
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000, discount = 0, vat = 2100, voucher = 1000
  // total = 10000 - 0 + 2100 - 1000 = 11100
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 2100);
  assert.equal(totals.voucher, 1000);
  assert.equal(totals.total, 11100);
});

test('invoiceTotals with discount and voucher', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 50, vatRate: 21 }],
    voucher: { code: 'SAVE5', amount: 500 },
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000, discount = 5000, after = 5000, vat = 1050
  // total = 10000 - 5000 + 1050 - 500 = 5550
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 5000);
  assert.equal(totals.vat, 1050);
  assert.equal(totals.voucher, 500);
  assert.equal(totals.total, 5550);
});

test('invoiceTotals clamps total at 0 after voucher', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    voucher: { code: 'FREE', amount: 20000 },
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 10000, discount = 0, vat = 0, voucher = 20000
  // total would be -10000 but clamped at 0
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 20000);
  assert.equal(totals.total, 0);
});

test('applyVoucher applies voucher to draft invoice', () => {
