});

test('applyVoucher affects invoiceTotals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  const totalsBeforeVoucher = invoiceTotals(r.value);
  const vResult = applyVoucher(r.value, { code: 'SAVE500', amount: 500 });
